export const SlotStatus = {
    OPEN: 'OPEN',
    BOOKED: 'BOOKED',
    HOLD: 'HOLD',
    COMPLETED: 'COMPLETED',
    NEEDS_REBOOK: 'NEEDS_REBOOK'
};

export class AppointmentSlot {
    constructor(init) {
        Object.assign(this, init);
    }
}
